const jumpCodes=new Set(['Space','ArrowUp','KeyW']);
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(document.querySelector('dialog[open]')){if($('quiz').open&&/^[1-4]$/.test(e.key)&&!e.repeat)answerQuiz(Number(e.key)-1);if($('quiz').open&&e.key==='Enter'&&!$('continue').hidden){e.preventDefault();closeQuiz()}return}if($('game').hidden||isTeacher())return;if(e.code==='KeyX'){e.preventDefault();if(!e.repeat)castBubble();return}if(e.code==='Enter'&&reviveNeeded){e.preventDefault();openQuiz(true);return}if(['ArrowLeft','ArrowRight','KeyA','KeyD',...jumpCodes].includes(e.code)){e.preventDefault();if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=true;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=true;if(jumpCodes.has(e.code)&&!e.repeat)input.press(e.code,simTime())}});
window.addEventListener('keyup',e=>{if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=false;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=false;if(jumpCodes.has(e.code))input.release(e.code,simTime())});
window.addEventListener('blur',()=>{input.clear();keys={}});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
$('touchJump').onpointerdown=e=>{e.preventDefault();$('touchJump').setPointerCapture(e.pointerId);input.press('touch',simTime())};$('touchJump').onpointerup=$('touchJump').onpointercancel=()=>input.release('touch',simTime());
